eadyOpen"])		return	end		local nEventType = tJanCelePack_Data["Times"]["Event"]	local nDataType = tJanCelePack_Data["Times"]["Type"]	local nData = Get_UserStatisticValue(nEventType,nDataType)	local nUserMetempsychosis = Get_UserMetempsychosis()		-- 2转以上，转世处理	if nUserMetempsychosis >= 2 then		nUserMetempsychosis = 2	end		-- 对掩码值进行分解，取出总的次数跟今天的次数	local nNowSingleData = nData % 10000	local nNowTotalData = (nData - nNowSingleData) / 10000	local nTimes = nNowTotalData + 1		tItem[3301790]["OptionFunc2"] = string.format("JanCelePack_Open</N>3301790</N>%d</N>%d",nUserMetempsychosis,nTimes)		if nNowTotalData <= 1 then		tItem[3301790]["Text121"] = string.format(tJanCelePack_Text[3301790]["Text121"],nTimes,tJanCelePack_Text[nUserMetempsychosis][nTimes])		LinkItemGossipFunc_New(nItemId,"1-2")	elseif nNowTotalData == 2 then		tItem[3301790]["Text131"] = string.format(tJanCelePack_Text[3301790]["Text131"],tJanCelePack_Text[nUserMetempsychosis][nTimes])		LinkItemGossipFunc_New(nItemId,"1-3")	endend--------------------------------------物品配置-------------------------------------------tItem[3301790] = tItem[3301790] or {}tItem[3301790]["DialogueText"] = tJanCelePack_Text[3301790]tItem[3301790]["Function"] = function(nItemId)	JanCelePack_Chk(nItemId)end-- 等级不足时tItem[3301790]["Text1-1"] = {111,112}tItem[3301790]["tOption1-1"] = {1}-- 前两次打开tItem[3301790]["Text1-2"] = {121,122}tItem[3301790]["tOption1-2"] = {2,3,4,5}tItem[3301790]["OptionPoint3"] = "2-1"tItem[3301790]["OptionPoint4"] = "3-1"tItem[3301790]["OptionPoint5"] = "4-1"tItem[3301790]["Text2-1"] = {211,212,213,214,215,216,217,218,219}tItem[3301790]["tOption2-1"] = {9}tItem[3301790]["Text3-1"] = {311,312,313,314,315,316,317,318,319}tItem[3301790]["tOption3-1"] = {9}tItem[3301790]["Text4-1"] = {411,412,413,414,415,416,417,418,419}tItem[3301790]["tOption4-1"] = {9}-- 最后一次打开tItem[3301790]["Text1-3"] = {131,132}tItem[3301790]["tOption1-3"] = {2,3,4,5}----------------------------